"""Ideal op-amp circuit solver based on Modified Nodal Analysis (MNA).

Extends standard nodal analysis with ideal op-amp constraints:

  * Virtual short:   V(n+) - V(n-) = 0        -> one extra equation
  * Zero input bias: inputs draw no current     -> nothing stamped on input rows
  * Ideal output:    the output node is fed by an unknown current Iout that the
                     op-amp supplies; Iout becomes an extra unknown, and its
                     KCL contribution appears on the output node row.

Elements supported:
  resistor R a b value            (conductance stamps)
  vsource  V n+ n- value          (extra branch unknown + defining equation)
  opamp    O n+ n- nout           (virtual short equation + extra current)
Node "0" or "gnd" is the reference (ground). Node names are arbitrary strings.
"""

from __future__ import annotations

import numpy as np

GROUND_NAMES = {"0", "gnd", "GND", "ground"}


class Circuit:
    def __init__(self) -> None:
        self._node_index: dict[str, int] = {}
        self.resistors: list[tuple[str, str, str, float]] = []
        self.vsources: list[tuple[str, str, str, float]] = []
        self.opamps: list[tuple[str, str, str, str]] = []

    # ------------------------------------------------------------------ build
    def _idx(self, node: str) -> int | None:
        """Index of a non-ground node, or None for ground."""
        if node in GROUND_NAMES:
            return None
        if node not in self._node_index:
            self._node_index[node] = len(self._node_index)
        return self._node_index[node]

    def resistor(self, name: str, a: str, b: str, resistance: float) -> None:
        if resistance <= 0:
            raise ValueError(f"{name}: resistance must be positive")
        self.resistors.append((name, a, b, float(resistance)))

    def vsource(self, name: str, nplus: str, nminus: str, voltage: float) -> None:
        self.vsources.append((name, nplus, nminus, float(voltage)))

    def opamp(self, name: str, nplus: str, nminus: str, nout: str) -> None:
        self.opamps.append((name, nplus, nminus, nout))

    @classmethod
    def from_netlist(cls, text: str) -> "Circuit":
        """Parse a simple netlist. Blank lines and lines starting with '#' or
        '*' are ignored. Element letters: R, V, O."""
        ckt = cls()
        for raw in text.splitlines():
            line = raw.strip()
            if not line or line[0] in "#*":
                continue
            t = line.split()
            kind = t[0][0].upper()
            if kind == "R":
                ckt.resistor(t[0], t[1], t[2], float(t[3]))
            elif kind == "V":
                ckt.vsource(t[0], t[1], t[2], float(t[3]))
            elif kind == "O":
                ckt.opamp(t[0], t[1], t[2], t[3])
            else:
                raise ValueError(f"unknown element line: {line!r}")
        return ckt

    # ------------------------------------------------------------------ solve
    def solve(self) -> dict[str, dict[str, float]]:
        """Solve the DC operating point.

        Returns {"nodes": {name: V}, "opamp_currents": {name: Iout},
                 "vsource_currents": {name: I}}.
        Currents follow the passive sign convention: positive vsource current
        flows from n+ through the source to n-; positive op-amp current flows
        out of the output pin into the circuit.
        """
        # Assign indices lazily so every referenced node exists even if it
        # only touches an op-amp input.
        for _, a, b, _r in self.resistors:
            self._idx(a)
            self._idx(b)
        for _, p, m, _v in self.vsources:
            self._idx(p)
            self._idx(m)
        for _, np_, nm_, no in self.opamps:
            self._idx(np_)
            self._idx(nm_)
            self._idx(no)

        n_nodes = len(self._node_index)
        n_vs = len(self.vsources)
        n_oa = len(self.opamps)
        size = n_nodes + n_vs + n_oa
        A = np.zeros((size, size))
        z = np.zeros(size)

        inv_node = {i: name for name, i in self._node_index.items()}

        def stamp_g(i: int, j: int, g: float) -> None:
            A[i, j] += g

        # Resistors: conductance stamps into KCL rows.
        for _name, a, b, r in self.resistors:
            ia, ib = self._node_index.get(a), self._node_index.get(b)
            g = 1.0 / r
            if ia is not None:
                stamp_g(ia, ia, g)
                if ib is not None:
                    stamp_g(ia, ib, -g)
            if ib is not None:
                stamp_g(ib, ib, g)
                if ia is not None:
                    stamp_g(ib, ia, -g)

        vs_off = n_nodes
        oa_off = n_nodes + n_vs

        # Voltage sources: branch current unknown + defining equation.
        for k, (_name, p, m, v) in enumerate(self.vsources):
            ip = self._node_index.get(p)
            im = self._node_index.get(m)
            if ip is not None:
                A[ip, vs_off + k] += 1.0
            if im is not None:
                A[im, vs_off + k] -= 1.0
            if ip is not None:
                A[vs_off + k, ip] += 1.0
            if im is not None:
                A[vs_off + k, im] -= 1.0
            z[vs_off + k] = v

        # Ideal op-amps:
        #   * output node KCL gets +Iout (op-amp drives the node),
        #   * extra row enforces the virtual short V+ - V- = 0,
        #   * inputs draw no current: no stamps at n+/n- rows.
        for k, (_name, nplus, nminus, nout) in enumerate(self.opamps):
            io = self._node_index.get(nout)
            if io is not None:
                A[io, oa_off + k] += 1.0
            ip = self._node_index.get(nplus)
            im = self._node_index.get(nminus)
            if ip is not None:
                A[oa_off + k, ip] += 1.0
            if im is not None:
                A[oa_off + k, im] -= 1.0

        if size == 0:
            raise ValueError("empty circuit")

        x, *_ = np.linalg.lstsq(A, z, rcond=None)

        # Sanity check: system should be exactly solvable.
        if not np.allclose(A @ x, z, atol=1e-8):
            raise ValueError("circuit has no well-defined DC solution "
                             "(singular MNA matrix)")

        nodes = {inv_node[i]: float(x[i]) for i in range(n_nodes)}
        return {
            "nodes": {"0": 0.0, **nodes},
            "opamp_currents": {
                self.opamps[k][0]: float(x[oa_off + k]) for k in range(n_oa)
            },
            "vsource_currents": {
                self.vsources[k][0]: float(x[vs_off + k]) for k in range(n_vs)
            },
        }

    def v(self, node: str, solution: dict | None = None) -> float:
        sol = solution if solution is not None else self.solve()
        return sol["nodes"][node]

