from __future__ import annotations

import re

import numpy as np

_SI_SUFFIXES = {"f": -15, "p": -12, "n": -9, "u": -6, "m": -3,
                "k": 3, "K": 3, "M": 6, "meg": 6, "MEG": 6, "G": 9}


def parse_value(token: str) -> float:
    """Parse a numeric value with an optional SPICE-style SI suffix,
    e.g. '1k' -> 1000.0, '4.7u' -> 4.7e-6, '2Meg' -> 2e6."""
    t = token.strip()
    m = re.fullmatch(r"([+-]?\d*\.?\d+(?:[eE][+-]?\d+)?)\s*([a-zA-Z]*)", t)
    if not m:
        raise ValueError(f"cannot parse value: {token!r}")
    val = float(m.group(1))
    suffix = m.group(2)
    if suffix:
        if suffix[:3].lower() == "meg":
            val *= 1e6
        elif suffix[0] in _SI_SUFFIXES:
            val *= 10.0 ** _SI_SUFFIXES[suffix[0]]
        else:
            raise ValueError(f"unknown unit suffix in {token!r}")
    return val

